async def act(page):
    """
    Navigate to likely Magento Admin 'Orders by Period' report pages and extract monthly
    successful order counts for Jan-Nov 2022. Returns a newline-separated string with
    lines in MM:COUNT format for months 01..11.
    """
    import re

    # Candidate relative report paths to try (use relative goto)
    candidate_paths = [
        '/index.php/admin/report/sales/order/period/',
        '/index.php/admin/report/sales/order/',
        '/index.php/admin/report_sales/order/period/',
        '/index.php/admin/report_sales/order/',
        '/index.php/admin/report/',
        '/index.php/admin/sales/order/index/'
    ]

    month_map = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04', 'may': '05', 'jun': '06',
        'jul': '07', 'aug': '08', 'sep': '09', 'sept': '09', 'oct': '10', 'nov': '11', 'dec': '12'
    }

    month_regex = re.compile(r"\b(?:(Jan|January|Feb|February|Mar|March|Apr|April|May|Jun|June|Jul|July|Aug|August|Sep|Sept|September|Oct|October|Nov|November|Dec|December))\b", re.IGNORECASE)
    year_regex = re.compile(r"\b(20\d{2})\b")
    number_regex = re.compile(r"(\d{1,3}(?:,\d{3})*|\d+)")

    def normalize_text(s: str) -> str:
        if not s:
            return ''
        return s.replace('\u00A0', ' ').replace('\t', ' ')

    def parse_text_for_month_counts(text: str):
        text = normalize_text(text)
        lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
        counts = {}
        for ln in lines:
            m_mon = month_regex.search(ln)
            m_year = year_regex.search(ln)
            if m_mon and m_year and m_year.group(1) == '2022':
                nums = number_regex.findall(ln)
                if not nums:
                    continue
                last_num = nums[-1].replace(',', '')
                try:
                    _ = int(last_num)
                except Exception:
                    continue
                mon_key = m_mon.group(1)[:3].lower()
                mm = month_map.get(mon_key)
                if mm and mm not in counts:
                    counts[mm] = str(int(last_num))
        return counts

    found_counts = None

    # Try candidate pages using relative goto
    for path in candidate_paths:
        try:
            await page.goto(path)
            await page.wait_for_timeout(800)

            tables = page.get_by_role('table')
            table_count = await tables.count()
            for i in range(table_count):
                tbl = tables.nth(i)
                try:
                    txt = await tbl.inner_text()
                except Exception:
                    continue
                counts = parse_text_for_month_counts(txt)
                if counts and len(counts) >= 3:
                    found_counts = counts
                    break
            if found_counts:
                break
        except Exception:
            # Try next candidate on any error
            continue

    # Fallback: scan full document text
    if not found_counts:
        try:
            doc_txt = await page.inner_text('document')
            counts = parse_text_for_month_counts(doc_txt)
            if counts and len(counts) >= 3:
                found_counts = counts
        except Exception:
            pass

    if not found_counts:
        # If no data found, raise so caller can surface this situation
        raise RuntimeError('Could not locate a month-by-month 2022 orders table (Jan-Nov) on the admin site.')

    months_order = ['01','02','03','04','05','06','07','08','09','10','11']
    lines = []
    for mm in months_order:
        cnt = found_counts.get(mm, '0')
        lines.append(f"{mm}:{cnt}")

    return '\n'.join(lines)

